      {"t":"type","p":"I'm looking for a cheap hotel.","a":["Saya mencari hotel murah.","Saya sedang mencari hotel murah."],"hint":"cari · hotel · murah","x":["mengcari"],"why":"murah comes after the noun: hotel murah; cari becomes mencari."},
      {"t":"type","p":"My father is writing a letter.","a":["Ayah saya sedang menulis surat.","Ayah saya menulis surat.","Ayahku sedang menulis surat.","Ayahku menulis surat.","Bapak saya sedang menulis surat.","Bapak saya menulis surat.","Bapakku sedang menulis surat.","Bapakku menulis surat."],"hint":"ayah · tulis · surat","x":["mentulis"],"why":"The owner comes after the noun: ayah saya; tulis becomes menulis."},
      {"t":"type","p":"I haven't cooked yet.","a":["Saya belum memasak.","Belum memasak."],"hint":"belum · masak","x":["bermasak"],"why":"belum is the time word for not yet; masak becomes memasak."}
